/// <summary>
///  GRN search process for pending vendor invoices associated with EDI invoices.
/// </summary>
class METEDIInvoiceGRNSearchController extends SysOperationServiceController
{
}

Method.Source:
 /// <summary>
/// GRN search process for pending vendor invoices associated with EDI invoices.
/// </summary>
/// <param name = "_args"> args </param>
 public static void main(Args _args)
 {
     METEDIInvoiceGRNSearchController controller =
         new METEDIInvoiceGRNSearchController(
             classStr(METEDIInvoiceGRNSearchService),
             methodStr(METEDIInvoiceGRNSearchService, process));

     controller.parmExecutionMode(
         SysOperationExecutionMode::Asynchronous);

     controller.parmDialogCaption("@MET:EDIInvWaitingForGRN");
     controller.startOperation();
 }

/// <summary>
/// Batch job caption.
/// </summary>
/// <returns>Caption.</returns>
public ClassDescription caption()
{
    return "@MET:EDIInvWaitingForGRN";
}
